import sys, json

data = sys.stdin.read()
with open('after-cpm-packages.json', 'w') as f:
    f.write(data)

after = json.loads(data)
before = json.load(open('baseline-packages.json'))

def get_pkgs(d):
    result = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            tfm = f['framework']
            for pkg in f['topLevelPackages']:
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkgs(before)
a = get_pkgs(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

print('=== CHANGES ===')
changes = False
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes = True
        proj, tfm, pkg = k
        if bv is None:
            print(f'  ADDED: {proj} ({tfm}): {pkg} -> {av}')
        elif av is None:
            print(f'  REMOVED: {proj} ({tfm}): {pkg} was {bv}')
        else:
            print(f'  CHANGED: {proj} ({tfm}): {pkg} {bv} -> {av}')

if not changes:
    print('  (none)')

print()
print('=== UNCHANGED ===')
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv == av:
        proj, tfm, pkg = k
        print(f'  {proj} ({tfm}): {pkg} {av}')
"", "description": "Compare baseline vs post-conversion", "initial_wait": 60}
